<?php

namespace Database\Seeders;

use App\Models\Promovido;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Facades\Artisan;

class PoblarFotosPromovidosSeeder extends Seeder
{
    /**
     * Run the database seeds.
     */
    public function run(): void
    {
        // 1. Asegurar que exista el symlink de storage
        if (!file_exists(public_path('storage'))) {
            $this->command->info('Creando enlace simbólico storage:link...');
            Artisan::call('storage:link');
        }

        // 2. Crear el directorio 'fotos' en el disco público si no existe
        if (!Storage::disk('public')->exists('fotos')) {
            Storage::disk('public')->makeDirectory('fotos');
        }

        // 3. Crear una imagen placeholder (un círculo azul en formato PNG)
        $base64Png = '';

        $imagePath = 'fotos/placeholder.png';
        Storage::disk('public')->put($imagePath, base64_decode($base64Png));
        $this->command->info('Imagen placeholder creada en storage/app/public/fotos/placeholder.png');

        // 4. Asignar la foto a todos los promovidos que no tengan una foto asignada
        $this->command->info('Asignando foto placeholder a promovidos...');
        $updated = Promovido::whereNull('foto')
            ->orWhere('foto', '')
            ->update(['foto' => $imagePath]);

        $this->command->info("Se actualizó la foto de {$updated} promovidos.");
    }
}
